#define MANIFEST_SIZE 80u
#define MANIFEST_VERSION 2u
#define WAL_VERSION 1u
#define WAL_HEADER_SIZE 48u
#define WAL_MAGIC "JOBDBWAL"
#define WAL_MAX_PAYLOAD (16u * 1024u * 1024u)
#define RECORD_HEADER_SIZE 68u
#define RECORD_MAGIC "JOBDBREC"
#define EXECUTION_RECORD_TYPE 3u
#define EXECUTION_PAYLOAD_SIZE 120u
#define SCHEDULE_RECORD_TYPE 2u
#define SCHEDULE_PAYLOAD_SIZE 96u
#define STATS_RECORD_TYPE 5u
#define LEDGER_RECORD_TYPE 4u
#define STATS_PAYLOAD_SIZE 64u
#define LEDGER_PAYLOAD_SIZE 80u
static const uint8_t MAGIC[8] = {'J','O','B','D','B','M','A','N'};
struct jobdb { char *path; uint64_t database_id; uint64_t generation; uint64_t last_transaction_id; uint64_t last_checkpoint_transaction; uint64_t next_execution_id; uint32_t feature_flags; jobdb_failure_point_t failure_point; };
