typedef struct tx_op { uint32_t type,target_type; uint64_t target_id,txid; uint64_t expected_revision; tx_precondition_t precondition; uint8_t *payload; uint32_t payload_size; } tx_op_t;
struct jobdb_tx { jobdb_t *db; uint64_t id; int begun; int committed; size_t op_count,op_capacity; tx_op_t *ops; };
