typedef struct { uint32_t type; uint64_t *ids; size_t capacity; size_t count; } record_ids_context_t;
static int collect_record_id(const char *name, void *context) { record_ids_context_t *c=(record_ids_context_t*)context; unsigned type=0; unsigned long long id=0; char extra; if(sscanf(name,"record.%u.%llu%c",&type,&id,&extra)==2&&type==c->type&&id>0){if(c->ids&&c->count<c->capacity)c->ids[c->count]=(uint64_t)id;c->count++;}return 1; }
static jobdb_result_t load_record_ids(jobdb_t *db,uint32_t type,uint64_t **out,size_t *count){size_t n=0;uint64_t *ids=NULL;jobdb_result_t r=jobdb_list_record_ids(db,type,NULL,0,&n);if(r!=JOBDB_OK||n==0){*out=NULL;*count=n;return r;}ids=(uint64_t*)malloc(n*sizeof *ids);if(!ids)return JOBDB_ERR_INTERNAL;r=jobdb_list_record_ids(db,type,ids,n,&n);if(r!=JOBDB_OK){free(ids);return r;}*out=ids;*count=n;return JOBDB_OK;}
typedef struct { jobdb_t *db; jobdb_result_t result; } verify_context_t;
static int verify_record_file(const char *name, void *context) {
    verify_context_t *v=(verify_context_t*)context; unsigned type=0; unsigned long long id=0; char extra;
    if(sscanf(name,"record.%u.%llu%c",&type,&id,&extra)==2&&type>0&&id>0) {
        jobdb_record_t r; v->result=record_read(v->db,type,(uint64_t)id,&r);
        if(v->result==JOBDB_OK) jobdb_record_free(&r); else return 0;
    }
    return 1;
}
static jobdb_result_t verify_records(jobdb_t *db){
    verify_context_t v={db,JOBDB_OK}; jobdb_result_t x=jobdb_visit_files(db->path,verify_record_file,&v);
    return x==JOBDB_ERR_NOT_FOUND?JOBDB_OK:(x==JOBDB_OK?v.result:x);
}
