static jobdb_result_t record_create_raw(jobdb_t*db,uint32_t type,uint64_t id,const void*payload,uint32_t size){if(!db||!type||!id||(size&&!payload)||size>WAL_MAX_PAYLOAD)return JOBDB_ERR_INVALID_ARGUMENT;jobdb_record_t old;jobdb_result_t x=record_read(db,type,id,&old);if(x==JOBDB_OK){jobdb_record_free(&old);return JOBDB_ERR_ALREADY_EXISTS;}if(x!=JOBDB_ERR_NOT_FOUND)return x;jobdb_record_t r={type,1,id,db->generation,1,0,0,(uint8_t*)payload,size};return record_write(db,&r);}
jobdb_result_t jobdb_record_get(jobdb_t*db,uint32_t type,uint64_t id,jobdb_record_t*out){if(!db||!out||!type||!id)return JOBDB_ERR_INVALID_ARGUMENT;return record_read(db,type,id,out);}
static jobdb_result_t record_update_raw(jobdb_t*db,uint32_t type,uint64_t id,uint64_t expected,const void*payload,uint32_t size,uint64_t*out_revision){if(!db||!type||!id||(size&&!payload)||size>WAL_MAX_PAYLOAD)return JOBDB_ERR_INVALID_ARGUMENT;jobdb_record_t r;jobdb_result_t x=record_read(db,type,id,&r);if(x!=JOBDB_OK)return x;if(r.revision!=expected){jobdb_record_free(&r);return JOBDB_ERR_CONFLICT;}r.revision++;r.generation=db->generation;r.payload=(uint8_t*)payload;r.payload_size=size;x=record_write(db,&r);r.payload=NULL;jobdb_record_free(&r);if(x==JOBDB_OK&&out_revision)*out_revision=expected+1;return x;}
static jobdb_result_t record_delete_raw(jobdb_t*db,uint32_t type,uint64_t id,uint64_t expected){if(!db||!type||!id)return JOBDB_ERR_INVALID_ARGUMENT;jobdb_record_t r;jobdb_result_t x=record_read(db,type,id,&r);if(x!=JOBDB_OK)return x;if(r.revision!=expected){jobdb_record_free(&r);return JOBDB_ERR_CONFLICT;}char p[4096];record_path(p,sizeof p,db->path,type,id);jobdb_record_free(&r);return jobdb_remove_file(p);}
jobdb_result_t jobdb_record_create(jobdb_t*db,uint32_t type,uint64_t id,const void*payload,uint32_t size){jobdb_tx_t*tx=NULL;jobdb_result_t r;if(!db||!type||!id||(size&&!payload)||size>WAL_MAX_PAYLOAD)return JOBDB_ERR_INVALID_ARGUMENT;r=jobdb_tx_begin(db,&tx);if(r!=JOBDB_OK)return r;r=jobdb_tx_put(tx,type,id,payload,size);if(r==JOBDB_OK){tx->ops[tx->op_count-1].precondition=TX_PRECONDITION_CREATE;r=jobdb_tx_commit(tx);}jobdb_tx_rollback(tx);return r;}
