jobdb_result_t jobdb_open(const char *path, jobdb_t **out_db){ if(!path||!out_db||!*path)return JOBDB_ERR_INVALID_ARGUMENT;*out_db=NULL;uint64_t id=0,g=0,tx=0,cp=0,ex=1;uint32_t fl=0;jobdb_result_t r=load_manifests(path,&id,&g,&tx,&cp,&ex,&fl);if(r!=JOBDB_OK)return r;jobdb_t*db=(jobdb_t*)calloc(1,sizeof*db);if(!db)return JOBDB_ERR_INTERNAL;db->path=dupstr(path);if(!db->path){free(db);return JOBDB_ERR_INTERNAL;}db->database_id=id;db->generation=g;db->last_transaction_id=tx;db->last_checkpoint_transaction=cp;db->next_execution_id=ex;db->feature_flags=fl;jobdb_lock_t*l=NULL;r=jobdb_lock_acquire_impl(db,db->path,5000,&l);if(r==JOBDB_OK){r=wal_recover(db);jobdb_lock_release(l);}if(r!=JOBDB_OK){jobdb_close(db);return r;}*out_db=db;return JOBDB_OK; }
jobdb_result_t jobdb_tx_begin(jobdb_t *db, jobdb_tx_t **out_tx){if(!db||!out_tx)return JOBDB_ERR_INVALID_ARGUMENT;*out_tx=NULL;jobdb_tx_t*tx=(jobdb_tx_t*)calloc(1,sizeof*tx);if(!tx)return JOBDB_ERR_INTERNAL;tx->ops=(tx_op_t*)calloc(8,sizeof*tx->ops);if(!tx->ops){free(tx);return JOBDB_ERR_INTERNAL;}tx->op_capacity=8;tx->db=db;tx->begun=1;if(fail_now(db,JOBDB_FAILURE_AFTER_BEGIN)){free(tx->ops);free(tx);return JOBDB_ERR_IO;}*out_tx=tx;return JOBDB_OK;}
