static jobdb_result_t tx_apply(jobdb_tx_t*tx){for(size_t i=0;i<tx->op_count;i++){tx_op_t*op=&tx->ops[i];char p[4096];record_path(p,sizeof p,tx->db->path,op->target_type,op->target_id);if(op->type==3){if(remove(p)!=0&&errno!=ENOENT)return JOBDB_ERR_IO;continue;}jobdb_record_t old;uint64_t rev=1;jobdb_result_t r=record_read(tx->db,op->target_type,op->target_id,&old);if(r==JOBDB_OK){if(old.transaction_id==tx->id&&old.payload_size==op->payload_size&&(!op->payload_size||memcmp(old.payload,op->payload,op->payload_size)==0)){jobdb_record_free(&old);continue;}rev=old.revision+1;jobdb_record_free(&old);}else if(r!=JOBDB_ERR_NOT_FOUND)return r;jobdb_record_t rec={op->target_type,1,op->target_id,tx->db->generation,rev,tx->id,0,op->payload,op->payload_size};r=record_write(tx->db,&rec);if(r!=JOBDB_OK)return r;}return JOBDB_OK;}
jobdb_result_t jobdb_tx_commit(jobdb_tx_t *tx){jobdb_lock_t*l=NULL;jobdb_result_t r;if(!tx||!tx->begun||tx->committed)return JOBDB_ERR_INVALID_TRANSACTION;if(fail_now(tx->db,JOBDB_FAILURE_BEFORE_COMMIT))return JOBDB_ERR_IO;r=jobdb_lock_acquire(tx->db,5000,&l);if(r!=JOBDB_OK)return r;r=wal_recover(tx->db);if(r==JOBDB_OK){if(tx->db->last_transaction_id==UINT64_MAX)r=JOBDB_ERR_LIMIT;else tx->id=tx->db->last_transaction_id+1;for(size_t i=0;r==JOBDB_OK&&i<tx->op_count;i++){tx_op_t*op=&tx->ops[i];jobdb_record_t old;jobdb_result_t q=record_read(tx->db,op->target_type,op->target_id,&old);if(op->precondition==TX_PRECONDITION_CREATE){if(q==JOBDB_OK){jobdb_record_free(&old);r=JOBDB_ERR_ALREADY_EXISTS;}else if(q!=JOBDB_ERR_NOT_FOUND)r=q;}else if(op->precondition==TX_PRECONDITION_REVISION){if(q!=JOBDB_OK)r=q==JOBDB_ERR_NOT_FOUND?JOBDB_ERR_CONFLICT:q;else{if(old.revision!=op->expected_revision)r=JOBDB_ERR_CONFLICT;jobdb_record_free(&old);}}else if(q==JOBDB_OK)jobdb_record_free(&old);op->txid=tx->id;}if(r==JOBDB_OK)r=wal_append(tx->db,1,tx->id,0,0,NULL,0);for(size_t i=0;r==JOBDB_OK&&i<tx->op_count;i++)r=wal_append(tx->db,tx->ops[i].type,tx->id,tx->ops[i].target_type,tx->ops[i].target_id,tx->ops[i].payload,tx->ops[i].payload_size);if(r==JOBDB_OK)r=wal_append(tx->db,4,tx->id,0,0,NULL,0);if(r==JOBDB_OK)tx->committed=1;if(r==JOBDB_OK&&fail_now(tx->db,JOBDB_FAILURE_AFTER_COMMIT))r=JOBDB_ERR_IO;if(r==JOBDB_OK)r=tx_apply(tx);if(r==JOBDB_OK){tx->db->last_transaction_id=tx->id;uint8_t b[MANIFEST_SIZE];char p[4096];uint64_t g=tx->db->generation+1;manifest_encode(b,tx->db->database_id,g,tx->db->last_transaction_id,tx->db->last_checkpoint_transaction,tx->db->next_execution_id,tx->db->feature_flags);manifest_path(p,sizeof p,tx->db->path,(unsigned)(g&1u));r=jobdb_write_file(p,b,sizeof b);if(r==JOBDB_OK)tx->db->generation=g;}}jobdb_lock_release(l);return r;}
void jobdb_tx_rollback(jobdb_tx_t *tx){if(tx){for(size_t i=0;i<tx->op_count;i++)free(tx->ops[i].payload);free(tx->ops);free(tx);}}
void jobdb_test_fail_next(jobdb_t *db, jobdb_failure_point_t point){if(db)db->failure_point=point;}
jobdb_result_t jobdb_verify(const char *path){uint64_t id=0,g=0,tx=0,cp=0,ex=1;uint32_t fl=0;if(!path)return JOBDB_ERR_INVALID_ARGUMENT;jobdb_result_t x=load_manifests(path,&id,&g,&tx,&cp,&ex,&fl);if(x!=JOBDB_OK)return x;jobdb_t db={0};db.path=(char*)path;db.database_id=id;db.generation=g;db.last_transaction_id=tx;db.last_checkpoint_transaction=cp;db.next_execution_id=ex;db.feature_flags=fl;jobdb_lock_t*l=NULL;x=jobdb_lock_acquire_impl(&db,db.path,5000,&l);if(x!=JOBDB_OK)return x;x=wal_recover(&db);if(x==JOBDB_OK)x=verify_records(&db);jobdb_lock_release(l);return x;}
void jobdb_close(jobdb_t *db){if(db){free(db->path);free(db);}}
jobdb_result_t jobdb_lock_acquire(jobdb_t*db,uint32_t timeout_ms,jobdb_lock_t**out){if(!db||!out)return JOBDB_ERR_INVALID_ARGUMENT;return jobdb_lock_acquire_impl(db,db->path,timeout_ms,out);}
const char *jobdb_result_string(jobdb_result_t r){switch(r){case JOBDB_OK:return "OK";case JOBDB_ERR_INVALID_ARGUMENT:return "invalid argument";case JOBDB_ERR_NOT_FOUND:return "not found";case JOBDB_ERR_ALREADY_EXISTS:return "already exists";case JOBDB_ERR_IO:return "I/O error";case JOBDB_ERR_CORRUPT:return "corrupt";case JOBDB_ERR_VERSION:return "unsupported version";case JOBDB_ERR_LIMIT:return "limit";case JOBDB_ERR_INVALID_TRANSACTION:return "invalid transaction";case JOBDB_ERR_CONFLICT:return "conflict";case JOBDB_ERR_INVALID_STATE:return "invalid state";case JOBDB_ERR_BUSY:return "busy";case JOBDB_ERR_TIMEOUT:return "timeout";case JOBDB_ERR_STALE_LEASE:return "stale lease";default:return "internal";}}
